// The settings registry at run time: the getenv cache and the setenv wrappers that dm_settings.h puts in place of the libc calls (docs/ARCHITECTURE.md, Settings).
#include "dm_settings.h"
#include <stdio.h>
#include <string.h>
#include "dm_settings_names.h"   // generated by build.py from nxnative/dm/settings.tsv: dm_settings_names[], sorted

#undef getenv
#undef setenv
#undef unsetenv

static _Atomic unsigned g_gen = 1;   // a call site's cache holds the value of one generation; 0 is never current

static int is_dm(const char *n) { return n && n[0] == 'D' && n[1] == 'M' && n[2] == '_'; }

int dm_setting_known(const char *name) {
    size_t lo = 0, hi = sizeof dm_settings_names / sizeof *dm_settings_names;
    while (lo < hi) { size_t m = (lo + hi) / 2; int c = strcmp(dm_settings_names[m], name); if (!c) return 1; if (c < 0) lo = m + 1; else hi = m; }
    return 0;
}

// A record is never freed: another thread may still read the value it returned. A new one is made only when the value changed (bounded by the changes made)
const char *dm_env_cached(dm_env_rec *_Atomic *slot, const char *name) {
    if (!is_dm(name)) return getenv(name);
    unsigned g = atomic_load_explicit(&g_gen, memory_order_acquire);
    dm_env_rec *r = atomic_load_explicit(slot, memory_order_acquire);
    if (r && atomic_load_explicit(&r->gen, memory_order_relaxed) == g) return r->val;
    const char *v = getenv(name);
    if (r && (r->val == v || (r->val && v && !strcmp(r->val, v)))) { atomic_store_explicit(&r->gen, g, memory_order_relaxed); return r->val; }
    dm_env_rec *n = malloc(sizeof *n);
    if (!n) return v;
    n->val = v ? strdup(v) : NULL; atomic_init(&n->gen, g);
    if (v && !n->val) { free(n); return v; }
    atomic_store_explicit(slot, n, memory_order_release);
    return n->val;
}

static void unknown(const char *name) {   // once a name: a small table of the names already reported
    static char seen[16][64]; static _Atomic int nseen;
    if (!is_dm(name) || dm_setting_known(name)) return;
    int k = atomic_load(&nseen);
    for (int i = 0; i < k && i < 16; i++) if (!strncmp(seen[i], name, sizeof seen[i] - 1)) return;
    if (k < 16) { snprintf(seen[k], sizeof seen[k], "%s", name); atomic_store(&nseen, k + 1); }
    fprintf(stderr, "[dm] [RED] setting %s is not in nxnative/dm/settings.tsv: no code reads it (a typo?)\n", name);
}

int dm_setenv(const char *name, const char *value, int overwrite) {
    unknown(name);
    const char *old = getenv(name);
    if (old && (!overwrite || (value && !strcmp(old, value)))) return 0;
    int rc = setenv(name, value, overwrite);
    atomic_fetch_add_explicit(&g_gen, 1, memory_order_acq_rel);
    return rc;
}

int dm_unsetenv(const char *name) {
    if (!getenv(name)) return 0;
    int rc = unsetenv(name);
    atomic_fetch_add_explicit(&g_gen, 1, memory_order_acq_rel);
    return rc;
}
